1	syntax = "proto3";
2	
3	package memos.api.v1;
4	
5	import "api/v1/attachment_service.proto";
6	import "api/v1/common.proto";
7	import "google/api/annotations.proto";
8	import "google/api/client.proto";
9	import "google/api/field_behavior.proto";
10	import "google/api/resource.proto";
11	import "google/protobuf/empty.proto";
12	import "google/protobuf/field_mask.proto";
13	import "google/protobuf/timestamp.proto";
14	
15	option go_package = "gen/api/v1";
16	
17	service MemoService {
18	  // CreateMemo creates a memo. The request body is a Memo; set its content
19	  // (Markdown) and visibility (PRIVATE | PROTECTED | PUBLIC, default PRIVATE).
20	  // The memo is owned by the authenticated user; requires authentication.
21	  rpc CreateMemo(CreateMemoRequest) returns (Memo) {
22	    option (google.api.http) = {
23	      post: "/api/v1/memos"
24	      body: "memo"
25	    };
26	    option (google.api.method_signature) = "memo";
27	  }
28	  // ListMemos lists memos with pagination and filter.
29	  rpc ListMemos(ListMemosRequest) returns (ListMemosResponse) {
30	    option (google.api.http) = {get: "/api/v1/memos"};
31	    option (google.api.method_signature) = "";
32	  }
33	  // GetMemo gets a memo.
34	  rpc GetMemo(GetMemoRequest) returns (Memo) {
35	    option (google.api.http) = {get: "/api/v1/{name=memos/*}"};
36	    option (google.api.method_signature) = "name";
37	  }
38	  // UpdateMemo updates a memo.
39	  rpc UpdateMemo(UpdateMemoRequest) returns (Memo) {
40	    option (google.api.http) = {
41	      patch: "/api/v1/{memo.name=memos/*}"
42	      body: "memo"
43	    };
44	    option (google.api.method_signature) = "memo,update_mask";
45	  }
46	  // DeleteMemo deletes a memo.
47	  rpc DeleteMemo(DeleteMemoRequest) returns (google.protobuf.Empty) {
48	    option (google.api.http) = {delete: "/api/v1/{name=memos/*}"};
49	    option (google.api.method_signature) = "name";
50	  }
51	  // SetMemoAttachments replaces the full set of attachments on a memo with the
52	  // provided list (not an append). Pass the complete desired set; an empty list
53	  // clears all attachments. Idempotent.
54	  rpc SetMemoAttachments(SetMemoAttachmentsRequest) returns (google.protobuf.Empty) {
55	    option (google.api.http) = {
56	      patch: "/api/v1/{name=memos/*}/attachments"
57	      body: "*"
58	    };
59	    option (google.api.method_signature) = "name";
60	  }
61	  // ListMemoAttachments lists attachments for a memo.
62	  rpc ListMemoAttachments(ListMemoAttachmentsRequest) returns (ListMemoAttachmentsResponse) {
63	    option (google.api.http) = {get: "/api/v1/{name=memos/*}/attachments"};
64	    option (google.api.method_signature) = "name";
65	  }
66	  // SetMemoRelations replaces the full set of relations on a memo with the
67	  // provided list (not an append). Pass the complete desired set; an empty list
68	  // clears all relations. Idempotent.
69	  rpc SetMemoRelations(SetMemoRelationsRequest) returns (google.protobuf.Empty) {
70	    option (google.api.http) = {
71	      patch: "/api/v1/{name=memos/*}/relations"
72	      body: "*"
73	    };
74	    option (google.api.method_signature) = "name";
75	  }
76	  // ListMemoRelations lists relations for a memo.
77	  rpc ListMemoRelations(ListMemoRelationsRequest) returns (ListMemoRelationsResponse) {
78	    option (google.api.http) = {get: "/api/v1/{name=memos/*}/relations"};
79	    option (google.api.method_signature) = "name";
80	  }

1	import { timestampDate } from "@bufbuild/protobuf/wkt";
2	import { Code, ConnectError, createClient, type Interceptor } from "@connectrpc/connect";
3	import { createConnectTransport } from "@connectrpc/connect-web";
4	import { getAccessToken, hasStoredToken, isTokenExpired, REQUEST_TOKEN_EXPIRY_BUFFER_MS, setAccessToken } from "./auth-state";
5	import { AIService } from "./types/proto/api/v1/ai_service_pb";
6	import { AttachmentService } from "./types/proto/api/v1/attachment_service_pb";
7	import { AuthService } from "./types/proto/api/v1/auth_service_pb";
8	import { IdentityProviderService } from "./types/proto/api/v1/idp_service_pb";
9	import { InstanceService } from "./types/proto/api/v1/instance_service_pb";
10	import { MemoService } from "./types/proto/api/v1/memo_service_pb";
11	import { ShortcutService } from "./types/proto/api/v1/shortcut_service_pb";
12	import { UserService } from "./types/proto/api/v1/user_service_pb";
13	import { redirectOnAuthFailure } from "./utils/auth-redirect";
14	
15	interface RequestWithHeader {
16	  header: Headers;
17	}
18	
19	// ============================================================================
20	// Constants
21	// ============================================================================
22	
23	const RETRY_HEADER = "X-Retry";
24	const RETRY_HEADER_VALUE = "true";
25	
26	// ============================================================================
27	// Token Refresh State Management
28	// ============================================================================
29	
30	const createTokenRefreshManager = () => {
31	  let isRefreshing = false;
32	  let refreshPromise: Promise<void> | null = null;
33	
34	  return {
35	    async refresh(refreshFn: () => Promise<void>): Promise<void> {
36	      if (isRefreshing && refreshPromise) {
37	        return refreshPromise;
38	      }
39	
40	      isRefreshing = true;
41	      refreshPromise = refreshFn().finally(() => {
42	        isRefreshing = false;
43	        refreshPromise = null;
44	      });
45	
46	      return refreshPromise;
47	    },
48	  };
49	};
50	
51	const tokenRefreshManager = createTokenRefreshManager();
52	
53	// ============================================================================
54	// Token Refresh
55	// ============================================================================
56	
57	const fetchWithCredentials: typeof globalThis.fetch = (input, init) => {
58	  return globalThis.fetch(input, {
59	    ...init,
60	    credentials: "include",
61	  });
62	};
63	
64	// Separate transport without auth interceptor to prevent recursion
65	const refreshTransport = createConnectTransport({
66	  baseUrl: window.location.origin,
67	  useBinaryFormat: true,
68	  fetch: fetchWithCredentials,
69	  interceptors: [],
70	});
71	
72	const refreshAuthClient = createClient(AuthService, refreshTransport);
73	
74	async function doRefreshAccessToken(): Promise<void> {
75	  const response = await refreshAuthClient.refreshToken({});
76	
77	  if (!response.accessToken) {
78	    throw new ConnectError("Refresh token response missing access token", Code.Internal);
79	  }
80	
81	  const expiresAt = response.expiresAt ? timestampDate(response.expiresAt) : undefined;
82	  setAccessToken(response.accessToken, expiresAt);
83	}
84	
85	// All callers go through the manager to deduplicate concurrent refresh requests.
86	// This prevents race conditions between useTokenRefreshOnFocus (proactive refresh
87	// on tab focus) and the auth interceptor (reactive refresh on 401), which could
88	// otherwise send duplicate requests that conflict with server-side token rotation.
89	export async function refreshAccessToken(): Promise<void> {
90	  return tokenRefreshManager.refresh(doRefreshAccessToken);
91	}
92	
93	// ============================================================================
94	// Authentication Interceptor Helpers
95	// ============================================================================
96	
97	function setAuthorizationHeader(req: RequestWithHeader, token: string | null) {
98	  if (!token) return;
99	  req.header.set("Authorization", `Bearer ${token}`);
100	}
101	
102	function shouldHandleUnauthenticatedRetry(error: unknown, isRetryAttempt: boolean): boolean {
103	  if (!(error instanceof ConnectError)) {
104	    return false;
105	  }
106	  if (error.code !== Code.Unauthenticated) {
107	    return false;
108	  }
109	  if (isRetryAttempt) {
110	    return false;
111	  }
112	  return true;
113	}
114	
115	async function refreshAndGetAccessToken(): Promise<string> {
116	  await refreshAccessToken();
117	  const token = getAccessToken();
118	  if (!token) {
119	    throw new ConnectError("Token refresh succeeded but no token available", Code.Internal);
120	  }
121	  return token;
122	}
123	
124	export async function getRequestToken(): Promise<string | null> {
125	  let token = getAccessToken();
126	  if (!token) {
127	    if (!hasStoredToken()) return null;
128	    try {
129	      token = await refreshAndGetAccessToken();
130	    } catch {
131	      return null;
132	    }
133	    return token;
134	  }
135	
136	  // Preflight refresh: avoid sending requests with expired access tokens.
137	  // This is especially important for public endpoints (e.g. ListMemos), where
138	  // an expired token could otherwise be treated as anonymous and return
139	  // guest-scoped data before the reactive 401 refresh path runs.
140	  if (isTokenExpired(REQUEST_TOKEN_EXPIRY_BUFFER_MS)) {
141	    try {
142	      token = await refreshAndGetAccessToken();
143	    } catch {
144	      // Keep existing reactive 401 flow as fallback.
145	      // Protected methods still trigger refresh/redirect in the catch block below.
146	    }
147	  }
148	
149	  return token;
150	}
151	
152	// ============================================================================
153	// Authentication Interceptor
154	// ============================================================================
155	
156	const authInterceptor: Interceptor = (next) => async (req) => {
157	  const isRetryAttempt = req.header.get(RETRY_HEADER) === RETRY_HEADER_VALUE;
158	  const token = await getRequestToken();
159	  setAuthorizationHeader(req, token);
160	
161	  try {
162	    return await next(req);
163	  } catch (error) {
164	    if (!shouldHandleUnauthenticatedRetry(error, isRetryAttempt)) {
165	      throw error;
166	    }
167	
168	    try {
169	      const newToken = await refreshAndGetAccessToken();
170	      setAuthorizationHeader(req, newToken);
171	      req.header.set(RETRY_HEADER, RETRY_HEADER_VALUE);
172	      return await next(req);
173	    } catch (refreshError) {
174	      redirectOnAuthFailure();
175	      throw refreshError;
176	    }
177	  }
178	};
179	
180	// ============================================================================
181	// Transport & Service Clients
182	// ============================================================================
183	
184	const transport = createConnectTransport({
185	  baseUrl: window.location.origin,
186	  useBinaryFormat: true,
187	  fetch: fetchWithCredentials,
188	  interceptors: [authInterceptor],
189	});
190	
191	// Core service clients
192	export const instanceServiceClient = createClient(InstanceService, transport);
193	export const authServiceClient = createClient(AuthService, transport);
194	export const userServiceClient = createClient(UserService, transport);
195	
196	// Content service clients
197	export const memoServiceClient = createClient(MemoService, transport);
198	export const attachmentServiceClient = createClient(AttachmentService, transport);
199	export const aiServiceClient = createClient(AIService, transport);
200	export const shortcutServiceClient = createClient(ShortcutService, transport);
201	
202	// Configuration service clients
203	export const identityProviderServiceClient = createClient(IdentityProviderService, transport);
204

1	package v1
2	
3	import (
4		"net/http"
5	
6		"connectrpc.com/connect"
7		"google.golang.org/grpc/codes"
8		"google.golang.org/grpc/status"
9	
10		"github.com/usememos/memos/proto/gen/api/v1/apiv1connect"
11	)
12	
13	// ConnectServiceHandler wraps APIV1Service to implement Connect handler interfaces.
14	// It adapts the existing gRPC service implementations to work with Connect's
15	// request/response wrapper types.
16	//
17	// This wrapper pattern allows us to:
18	// - Reuse existing gRPC service implementations
19	// - Support both native gRPC and Connect protocols
20	// - Maintain a single source of truth for business logic.
21	type ConnectServiceHandler struct {
22		*APIV1Service
23	}
24	
25	// NewConnectServiceHandler creates a new Connect service handler.
26	func NewConnectServiceHandler(svc *APIV1Service) *ConnectServiceHandler {
27		return &ConnectServiceHandler{APIV1Service: svc}
28	}
29	
30	// RegisterConnectHandlers registers all Connect service handlers on the given mux.
31	func (s *ConnectServiceHandler) RegisterConnectHandlers(mux *http.ServeMux, opts ...connect.HandlerOption) {
32		// Register all service handlers
33		handlers := []struct {
34			path    string
35			handler http.Handler
36		}{
37			wrap(apiv1connect.NewInstanceServiceHandler(s, opts...)),
38			wrap(apiv1connect.NewAuthServiceHandler(s, opts...)),
39			wrap(apiv1connect.NewUserServiceHandler(s, opts...)),
40			wrap(apiv1connect.NewMemoServiceHandler(s, opts...)),
41			wrap(apiv1connect.NewAttachmentServiceHandler(s, opts...)),
42			wrap(apiv1connect.NewAIServiceHandler(s, opts...)),
43			wrap(apiv1connect.NewShortcutServiceHandler(s, opts...)),
44			wrap(apiv1connect.NewIdentityProviderServiceHandler(s, opts...)),
45		}
46	
47		for _, h := range handlers {
48			mux.Handle(h.path, h.handler)
49		}
50	}
51	
52	// wrap converts (path, handler) return value to a struct for cleaner iteration.
53	func wrap(path string, handler http.Handler) struct {
54		path    string
55		handler http.Handler
56	} {
57		return struct {
58			path    string
59			handler http.Handler
60		}{path, handler}
61	}
62	
63	// convertGRPCError converts gRPC status errors to Connect errors.
64	// This preserves the error code semantics between the two protocols.
65	func convertGRPCError(err error) error {
66		if err == nil {
67			return nil
68		}
69		if st, ok := status.FromError(err); ok {
70			return connect.NewError(grpcCodeToConnectCode(st.Code()), err)
71		}
72		return connect.NewError(connect.CodeInternal, err)
73	}
74	
75	// grpcCodeToConnectCode converts gRPC status codes to Connect error codes.
76	// gRPC and Connect use the same error code semantics, so this is a direct cast.
77	// See: https://connectrpc.com/docs/protocol/#error-codes
78	func grpcCodeToConnectCode(code codes.Code) connect.Code {
79		return connect.Code(code)
80	}
81
